// Example using a simple memory cache or Redis
app.get('/api/stats', async (req, res) => {
  // 1. Check if data is in Redis
  const cachedStats = await redis.get('app_stats');
  if (cachedStats) return res.json(JSON.parse(cachedStats));

  // 2. If not, do the heavy DB query
  const stats = await Database.calculateHeavyStats();

  // 3. Save to Redis for 1 hour, then send to client
  await redis.setex('app_stats', 3600, JSON.stringify(stats));
  res.json(stats);
});
